from solution import f
import math
import pytest
from hypothesis import given, strategies as st


def reference(n):
    """Obviously-correct direct translation of spec."""
    return [
        math.factorial(i) if i % 2 == 0 else i * (i + 1) // 2
        for i in range(1, n + 1)
    ]


# ---- concrete example from spec ----

def test_example_f5_equals_spec_list():
    assert f(5) == [1, 2, 6, 24, 15]


# ---- explicit small cases derived from spec ----

def test_first_element_is_sum_1_to_1():
    assert f(1) == [1]


def test_first_two_elements_match_spec():
    assert f(2) == [1, 2]


def test_first_three_elements_match_spec():
    assert f(3) == [1, 2, 6]


def test_first_four_elements_match_spec():
    assert f(4) == [1, 2, 6, 24]


def test_zero_returns_empty_list_of_size_zero():
    assert f(0) == []


# ---- properties ----

@given(st.integers(min_value=0, max_value=20))
def test_size_equals_n(n):
    result = f(n)
    assert isinstance(result, list)
    assert len(result) == n


@given(st.integers(min_value=0, max_value=20))
def test_values_match_reference_model(n):
    assert f(n) == reference(n)


@given(st.integers(min_value=1, max_value=20))
def test_even_positions_are_factorials(n):
    result = f(n)
    for i in range(1, n + 1):
        if i % 2 == 0:
            assert result[i - 1] == math.factorial(i)


@given(st.integers(min_value=1, max_value=20))
def test_odd_positions_are_triangular_sums(n):
    result = f(n)
    for i in range(1, n + 1):
        if i % 2 == 1:
            assert result[i - 1] == i * (i + 1) // 2
            assert result[i - 1] == sum(range(1, i + 1))


@given(st.integers(min_value=0, max_value=20))
def test_all_elements_are_positive_ints(n):
    result = f(n)
    for v in result:
        assert isinstance(v, int)
        assert v >= 1


@given(st.integers(min_value=1, max_value=15))
def test_prefix_consistency(n):
    # f(n) truncated to m must equal f(m): size-n list built per-index
    full = f(n + 5) if n + 5 <= 20 else f(n)
    # use bounded extension within strategy range
    m = n
    full_n = f(n)
    assert full_n[:m] == f(m)


@given(st.integers(min_value=1, max_value=18))
def test_recurrence_between_same_parity_entries(n):
    # odd i: T(i) = T(i-2) + (i-1) + i ; even i: F(i) = F(i-2)*(i-1)*i
    result = f(n)
    # need at least 3 elements to check stepping by 2
    if n >= 3:
        for i in range(3, n + 1):
            prev_same_parity = result[(i - 2) - 1]
            cur = result[i - 1]
            if i % 2 == 1:
                assert cur == prev_same_parity + (i - 1) + i
            else:
                assert cur == prev_same_parity * (i - 1) * i


def test_odd_entries_equal_direct_summation():
    # direct sum check for a fixed range, independent of formula
    result = f(10)
    for i in range(1, 11, 2):
        assert result[i - 1] == sum(range(1, i + 1))


def test_even_entries_equal_direct_product():
    # direct product check for a fixed range
    result = f(10)
    for i in range(2, 11, 2):
        prod = 1
        for k in range(1, i + 1):
            prod *= k
        assert result[i - 1] == prod
